    'course.welcome.title': 'Välkommen till Dataspatium',
    'course.welcome.p1': 'Dataspatium hämtar, bearbetar, analyserar, visualiserar och exporterar data helt i webbläsaren. Inget installeras, och dina data lämnar inte datorn utom när du själv hämtar från ett API.',
    'course.welcome.p2': 'Grundkursen tar ungefär tio minuter. Du följer ett konkret exempel, {example}, genom appens åtta lägen: {modes}. I varje steg kan du göra uppgiften själv eller låta kursen göra den åt dig.',
    'course.welcome.p3': 'Skärmen ser likadan ut i alla lägen: lägena överst, objektpanelen till vänster, arbetsytan i mitten, egenskaperna till höger och loggen längst ned. Kursen kan minimeras och öppnas igen från hjälpen.',
    'course.import.title': 'Inhämta: hämta data',
    'course.import.p1': 'All data i appen ligger i datamängder: tabeller med namngivna kolumner, där varje kolumn har en typ som text, heltal, tal eller datum. Data kan hämtas från filer (CSV, Excel, JSON, Parquet, SPSS med flera), inklistrad text, webbadresser och öppna API:er från myndigheter i hela Norden.',
    'course.import.task': 'Gå till {mode} och klicka på {button}. Då skapas datamängden {name}.',
    'course.import.done': 'Datamängden är skapad: 290 kommuner med kolumnerna kommunkod, kommun, lanskod, lan, ar och folkmangd. Kortnamnet är {short}.',
    'course.manage.title': 'Hantera: datamängder och arbetsytan',
    'course.manage.p1': 'Varje datamängd har ett namn och ett kortnamn. Kortnamnet, här {short}, har bara små bokstäver, siffror och understreck och används i SQL och R. I {mode} ser du källan, storleken, kolumnerna med typer och beskrivningar, och versioner som du kan gå tillbaka till.',
    'course.manage.p2': 'Allt sparas automatiskt i webbläsaren. Ta en säkerhetskopia av arbetsytan då och då med {backup}, så att inget går förlorat om webbläsarens data rensas.',
    'course.manage.task': 'Öppna {mode}, välj datamängden i objektpanelen och titta på uppgifterna och kolumnerna.',
    'course.manage.done': 'Här kan du också byta namn och kortnamn, dela datamängder som paket och ta bort dem.',
    'course.process.title': 'Bearbeta: rensa och beräkna',
    'course.process.p1': 'I {mode} ser du hela tabellen. Klicka på en kolumnrubrik för att sortera och se kolumnens profil med saknade värden, unika värden och fördelning. Rätta värden direkt i cellerna eller med åtgärder.',
    'course.process.p2': 'Varje ändring blir ett steg i datamängdens {recipe}. Stegen kan ångras, köras om på en ny version av data och kopieras som R- eller SQL-kod.',
    'course.process.task': 'Gör en kolumn med folkmängden i tusental: {mode} → {actions} → {group} → {op}. Ange namnet {column} och uttrycket {expression}.',
    'course.process.done': 'Kolumnen {column} ligger nu sist i tabellen, och steget finns i receptet.',
    'course.sql.title': 'Analysera: fråga med SQL',
    'course.sql.p1': '{mode} är läget för kod och statistik. I SQL-fliken heter den valda datamängden {data}, men alla datamängder kan också nås med sina kortnamn. Därför kan en fråga koppla ihop flera datamängder.',
    'course.sql.task': 'Öppna {mode} → {tab}, skriv frågan nedan och klicka på {run}. Frågan summerar folkmängden per län.',
    'course.sql.done': 'Stockholms län är störst med nästan 2,5 miljoner invånare, följt av Västra Götalands och Skåne län. Med {save} blir resultatet en ny datamängd.',
    'course.r.title': 'Analysera: räkna med R',
    'course.r.p1': 'R-fliken kör R direkt i webbläsaren, med paket som dplyr och ggplot2. {read} läser en datamängd som en data frame, och {write} sparar en data frame som en ny datamängd. Första gången tar det några sekunder att starta R.',
    'course.r.task': 'Öppna {mode} → {tab}, skriv koden nedan och klicka på {run}. Koden sammanfattar folkmängden och ritar ett histogram.',
    'course.r.done': 'Medianen är drygt 16 000 invånare: hälften av kommunerna är mindre än så, och den största, Stockholm, har nästan en miljon. Därför har diagrammet en logaritmisk skala.',
    'course.viz.title': 'Visualisera: gör ett diagram',
    'course.viz.p1': 'Diagram byggs med diagrambyggaren (Vega-Lite), färdiga D3-mallar eller R. Alla använder appens färger och typsnitt, ritas om när data ändras och kan samlas i dashboards med gemensamma filter.',
    'course.viz.task': 'Öppna {mode} → {new} → {builder}. Välj {type}, sätt {x} till lan ({y} är redan folkmangd) och klicka på {save}.',
    'course.viz.done': 'Diagrammet är sparat. Prova också diagramtypen {map} tillsammans med exempeldatamängden {boundaries} för att visa folkmängden på en karta.',
    'course.export.title': 'Exportera: dela resultatet',
    'course.export.p1': 'I {mode} sparar du data som CSV, Excel, JSON, Parquet, SQLite, SPSS med flera format, diagram som PNG, SVG, PDF eller PowerPoint och dokument från mallar som Word, PDF, HTML eller LaTeX, även ett dokument per grupp i en omgång.',
    'course.export.task': 'Öppna {mode}, välj till exempel formatet Excel och klicka på {run}.',
    'course.export.done': 'Filen hamnar bland webbläsarens hämtade filer. Flikarna {charts} och {documents} fungerar på samma sätt för diagram och dokument.',
    'course.finish.title': 'Klart: så går du vidare',
    'course.finish.p1': 'Du har gått igenom hela kedjan: hämta, hantera, bearbeta, analysera, visualisera och exportera.',
    'course.finish.p2': 'Gå vidare med egna data: släpp en fil i {import}, välj länder och hämta från ett öppet API, skriv anteckningsböcker med text, R och SQL i {analyse} eller gör dokumentmallar i {export}. Alt+1–6 byter läge och {palette} öppnar kommandopaletten.',
    'course.finish.p3': 'Kursen finns kvar under {help} och i kommandopaletten.',
